import math
    import random
    import time

    LANGUAGE_WRAPPER = "A long, thin strip of paper is {n} units long, 1 unit wide, and divided into {n} unit squares labeled 1 through {n} from left to right. It is folded exactly {k} times. The s-th fold (for s = 1, 2, ..., {k}) is specified by the string {folds}, read left to right: 'R' means the right end is folded over onto the left end, and 'L' means the left end is folded over onto the right end. After the last fold, the strip is a stack of {n} unit squares. How many squares lie strictly below the square that was originally the {target}-th square from the left?"

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose k moderately large to ensure nontrivial difficulty
k = rng.randint(9, 13)
n = 1 << k

# Generate a fold sequence with both L and R and at least 2 transitions
def gen_folds(k, rng):
    while True:
        # Bias slightly toward alternation to avoid trivial runs
        choices = []
        last = None
        for _ in range(k):
            if last is None:
                last = rng.choice(['L', 'R'])
            else:
                # 60% chance to switch, 40% to stay
                if rng.random() < 0.6:
                    last = 'L' if last == 'R' else 'R'
            choices.append(last)
        s = ''.join(choices)
        if 'L' not in s or 'R' not in s:
            continue
        transitions = sum(1 for i in range(1, k) if s[i] != s[i-1])
        if transitions < 2:
            continue
        # Avoid palindromic pattern which can be easier
        if s == s[::-1]:
            continue
        return s

folds = gen_folds(k, rng)

# Pick a nontrivial target index
# Avoid extreme ends and middle fold boundary to reduce trivialities
avoid = {1, n, n//2, n//2 + 1}
while True:
    target = rng.randint(1, n)
    if target not in avoid:
        break

return {'n': n, 'k': k, 'folds': folds, 'target': target}

    def verifier(assign):
# Validate presence of required fields
for key in ['n', 'k', 'folds', 'target']:
    if key not in assign:
        # Missing required field
        return (False, None)
n = assign['n']
