folds = assign['folds']
target = assign['target']

# Basic validations
if not isinstance(n, int) or not isinstance(k, int) or not isinstance(target, int):
    return (False, None)
if not isinstance(folds, str):
    return (False, None)
if k <= 0 or n <= 0:
    return (False, None)
if len(folds) != k:
    return (False, None)
if any(c not in 'LR' for c in folds):
    return (False, None)
if target < 1 or target > n:
    return (False, None)
# n must be a power of two and equal to 2^k
if n != 1 << k:
    return (False, None)

# Enforce nontrivial difficulty: both L and R present and at least 2 transitions
if 'L' not in folds or 'R' not in folds:
    return (False, None)
transitions = sum(1 for i in range(1, k) if folds[i] != folds[i-1])
if transitions < 2:
    return (False, None)

# Compute final position from top using the fold-half encoding
# v_s = 0 if the square lies in the flipping half at step s, else 1
# After each fold, update x to its coordinate in the halved strip.
x = target  # 1-indexed within current strip
p_top = 0   # position from top (0-based)
curr_n = n
for s in range(k):
    m = curr_n // 2
    f = folds[s]
    if f == 'R':
        if x <= m:
            v = 1  # stationary (left) -> placed below at this step
            # x unchanged
        else:
            v = 0  # flipped (right) -> placed above at this step
            x = curr_n - x + 1
    else:  # f == 'L'
        if x <= m:
            v = 0  # flipped (left)
            x = m - x + 1
        else:
            v = 1  # stationary (right)
            x = x - m
    p_top += v << s  # s-th fold contributes 2^s (least significant bit is first fold)
    curr_n = m

# Number strictly below equals total minus 1 minus position-from-top
answer = n - 1 - p_top
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

